import numpy as np
from scipy import stats
from sklearn.feature_selection import mutual_info_classif

MAX_DRIVERS = 5

def design(feats):
    # Identify strong features by t-statistic threshold
    strong_features = []
    for i, fid in enumerate(feats.ids):
        # The types array contains the t-statistics for each feature
        t_stat = feats.types[i]
        # Only consider numeric t-statistics
        if isinstance(t_stat, (int, float)) and not np.isnan(t_stat):
            if abs(t_stat) > 3.5:
                strong_features.append(fid)

    # Remove near-duplicates based on correlation
    seen = set()
    unique_features = []
    for fid in strong_features:
        if fid in seen:
            continue
        unique_features.append(fid)
        # Mark correlated features as seen
        for other_fid in strong_features:
            if other_fid != fid and other_fid not in seen:
                col_a = feats.column(fid)
                col_b = feats.column(other_fid)
                if col_a is not None and col_b is not None:
                    corr = np.corrcoef(feats.x[:, col_a], feats.x[:, col_b])[0, 1]
                    if abs(corr) >= 0.6:
                        seen.add(other_fid)

    # If no strong features or very few, return empty design
    if len(unique_features) < 2:
        return Design(drivers=(), columns=(), products=(), loadings={})

    # Check for potential causal drivers using mutual information
    mi_scores = mutual_info_classif(feats.x[:, [feats.column(fid) for fid in unique_features if feats.column(fid) is not None]], feats.y)
    sorted_indices = np.argsort(mi_scores)[::-1]
    drivers = tuple([unique_features[i] for i in sorted_indices[:MAX_DRIVERS]])

    # Build columns and products
    columns = tuple(unique_features)
    products = ()
    loadings = {}

    # Add top features to loadings for weighted score
    for i, fid in enumerate(unique_features[:3]):
        idx = feats.column(fid)
        if idx is not None:
            loadings[fid] = mi_scores[sorted_indices[i]]

    return Design(drivers=drivers, columns=columns, products=products, loadings=loadings)

